    const offStr = kv['clinic.utc_offset'] || '-07:00';
    const om = /^([+-])(\d{2}):(\d{2})$/.exec(offStr); if (!om) throw new Error('Config clinic.utc_offset invalid');
    const cfg = {
      name: kv['clinic.name'] || 'Meow Meow Veterinary Hospital',
      tz: kv['clinic.timezone'] || 'America/Phoenix', offsetStr: offStr,
      offsetMin: (om[1]==='-'?-1:1) * (+om[2]*60 + +om[3]),
      arenaNowStr: req('clinic.arena_now'),
      openDays: req('clinic.open_days').split(',').map(s=>s.trim()).filter(Boolean),
